{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM 是明示的组织及形成报告的参与者，ROLE 类型有文本支持。",
      "sources": [{"quote": "请 PM 组织备份读取检查并形成 backup-read.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "backup",
      "verdict": "SUPPORT",
      "reason": "备份是读取检查对象，并被明确禁止写入，支持 READ_ONLY_INPUT。",
      "sources": [
        {"quote": "备份读取检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "不得写入备份", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "report",
      "verdict": "SUPPORT",
      "reason": "文件是形成动作的生成输出；后续报告指称该文件有上下文支持。",
      "sources": [{"quote": "形成 backup-read.md，最多尝试 6 次；至少 3 次读取成功且报告已生成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "请求明确要求组织读取检查，支持 MAIN、REQUIRED 和 ORGANIZE。",
      "sources": [{"quote": "请 PM 组织备份读取检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "read_check",
      "verdict": "SUPPORT",
      "reason": "读取检查是组织动作的补足内容；未单独指定其执行者，UNSTATED 不额外提升执行义务。",
      "sources": [{"quote": "组织备份读取检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "generate_report",
      "verdict": "SUPPORT",
      "reason": "形成文件是与组织并列的明确要求，支持 REQUIRED 的生成事件。",
      "sources": [{"quote": "请 PM 组织备份读取检查并形成 backup-read.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "read_success",
      "verdict": "SUPPORT",
      "reason": "读取成功是完成条件中的验收状态，没有被提升为独立命令。",
      "sources": [{"quote": "至少 3 次读取成功且报告已生成时任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "report_generated",
      "verdict": "SUPPORT",
      "reason": "报告已生成是完成条件中的状态；状态本身的 UNSTATED 与前文生成动作的 REQUIRED 可以并存。",
      "sources": [{"quote": "报告已生成时任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "task_complete",
      "verdict": "SUPPORT",
      "reason": "文本明确陈述满足前述条件时任务完成，支持完成状态。",
      "sources": [{"quote": "至少 3 次读取成功且报告已生成时任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "write_backup",
      "verdict": "SUPPORT",
      "reason": "不得明确禁止写入备份；FORBIDDEN 表达禁止，AFFIRMATIVE 表达被禁止的动作内容。",
      "sources": [{"quote": "不得写入备份", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r1",
      "verdict": "SUPPORT",
      "reason": "PM 是组织动作的明示主语，PERFORMER 来自动词参与关系。",
      "sources": [{"quote": "PM 组织", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r2",
      "verdict": "NO_EVIDENCE",
      "reason": "文本支持读取检查是组织动作的对象或补足内容，但没有明确支持读取检查事件是组织事件的组成部分。owner 所表达的补足归属不能自动证明 PART_OF。",
      "sources": [{"quote": "组织备份读取检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r3",
      "verdict": "SUPPORT",
      "reason": "备份是读取检查所针对的数据材料，支持 PATIENT；该关系不意味着允许修改。",
      "sources": [{"quote": "备份读取检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r4",
      "verdict": "SUPPORT",
      "reason": "组织与形成共享明示主语 PM，支持 PM 参与形成报告。",
      "sources": [{"quote": "请 PM 组织备份读取检查并形成 backup-read.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r5",
      "verdict": "SUPPORT",
      "reason": "文件是形成动作的结果。",
      "sources": [{"quote": "形成 backup-read.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r6",
      "verdict": "SUPPORT",
      "reason": "并明确连接组织与形成两个谓词，支持并列关系，不声明执行先后。",
      "sources": [{"quote": "组织备份读取检查并形成 backup-read.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r7",
      "verdict": "SUPPORT",
      "reason": "读取检查、尝试次数及后续读取成功次数的连续上下文支持将尝试上限绑定到读取检查。",
      "sources": [{"quote": "备份读取检查并形成 backup-read.md，最多尝试 6 次；至少 3 次读取成功", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r8",
      "verdict": "SUPPORT",
      "reason": "前文唯一的读取对象是备份，后文读取成功承接该读取检查，支持对象共指。",
      "sources": [{"quote": "备份读取检查并形成 backup-read.md，最多尝试 6 次；至少 3 次读取成功", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r9",
      "verdict": "SUPPORT",
      "reason": "前文形成的文件与后文报告已生成构成可追溯的报告指称，支持状态主题绑定。",
      "sources": [{"quote": "形成 backup-read.md，最多尝试 6 次；至少 3 次读取成功且报告已生成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r10",
      "verdict": "SUPPORT",
      "reason": "合取条件明确控制任务完成，属于完成条件而非普通时间背景。",
      "sources": [{"quote": "至少 3 次读取成功且报告已生成时任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r11",
      "verdict": "SUPPORT",
      "reason": "完成状态明确属于任务。",
      "sources": [{"quote": "任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r12",
      "verdict": "SUPPORT",
      "reason": "禁止写入备份是当前任务的明确限制，没有另设适用条件。",
      "sources": [{"quote": "不得写入备份", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r13",
      "verdict": "SUPPORT",
      "reason": "备份是被禁止写入的目标材料。",
      "sources": [{"quote": "写入备份", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "attempt_cap",
      "verdict": "SUPPORT",
      "reason": "最多对应 LTE，6 次是尝试次数的执行上限，未要求必须尝试六次。",
      "sources": [{"quote": "备份读取检查并形成 backup-read.md，最多尝试 6 次；至少 3 次读取成功", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "success_threshold",
      "verdict": "SUPPORT",
      "reason": "至少对应 GTE，3 次计量成功读取次数，并用于任务完成验收。",
      "sources": [{"quote": "至少 3 次读取成功且报告已生成时任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "successful_reads_condition",
      "verdict": "SUPPORT",
      "reason": "表达式组合成功状态及其数量阈值，支持至少三次成功读取这一条件；没有新增独立执行要求。",
      "sources": [{"quote": "至少 3 次读取成功", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "read_success_ref",
      "verdict": "SUPPORT",
      "reason": "完成条件引用读取成功状态，STATE_REF 有文本支持。",
      "sources": [{"quote": "至少 3 次读取成功且报告已生成时任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "report_generated_ref",
      "verdict": "SUPPORT",
      "reason": "完成条件引用报告已生成状态，没有通过引用额外创造生成命令。",
      "sources": [{"quote": "报告已生成时任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "completion_condition",
      "verdict": "SUPPORT",
      "reason": "且明确要求成功读取数量条件与报告生成状态同时成立，支持 AND 完成条件。",
      "sources": [{"quote": "至少 3 次读取成功且报告已生成时任务完成", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    }
  ],
  "findings": [
    {
